const stdout = $('Get Jobs File').item.json.stdout || '{}';
let jobs = {};
try { jobs = JSON.parse(stdout); } catch (e) { jobs = {}; }

const chatIds = Object.keys(jobs);
if (chatIds.length === 0) return [];

return chatIds.map(chatId => ({
  json: {
    chatId,
    outfile: jobs[chatId].outfile,
    startTime: jobs[chatId].startTime,
    lastProgress: jobs[chatId].lastProgress || '',
    sessionId: jobs[chatId].sessionId || ''
  }
}));

const chatId = $('Parse Jobs').item.json.chatId;
const outfile = $('Parse Jobs').item.json.outfile;
const lastProgress = $('Parse Jobs').item.json.lastProgress;
const sessionId = $('Parse Jobs').item.json.sessionId;
const stdout = $('Check Job Status').item.json.stdout || '';

// Parse wrapper output format
const lines = stdout.split('\n');
let isComplete = false;
let isRunning = false;
let isWaiting = false;
let progress = '';
let finalResponse = '';
let jsonResult = null;

// Find last PROGRESS line and STATUS:COMPLETE
for (const line of lines) {
  if (line.startsWith('STATUS:COMPLETE')) isComplete = true;
  else if (line.startsWith('STATUS:RUNNING')) isRunning = true;
  else if (line.startsWith('STATUS:STARTING') || line.startsWith('STATUS:WAITING')) isWaiting = true;
  else if (line.startsWith('PROGRESS:')) {
    // Extract progress text after PROGRESS:N:
    const match = line.match(/^PROGRESS:\d+:\s*(.+)$/);
    if (match) progress = match[1].trim();
  }
}

// If complete, extract JSON result
if (isComplete) {
  const jsonLines = lines.filter(l => l.startsWith('{') && l.includes('"type":"result"'));
  if (jsonLines.length > 0) {
    try {
      jsonResult = JSON.parse(jsonLines[0]);
      finalResponse = jsonResult.result || 'Done!';
    } catch (e) {
      finalResponse = jsonLines[0];
    }
  } else {
    // Fallback: grab everything after STATUS:COMPLETE
    const idx = lines.findIndex(l => l.startsWith('STATUS:COMPLETE'));
    if (idx >= 0) finalResponse = lines.slice(idx + 1).filter(l => l && !l.startsWith('__CLAUDE')).join('\n');
  }
  finalResponse = finalResponse.replace(/\x1b\[[0-9;]*m/g, '');
}

// Clean up progress
if (progress) {
  progress = progress.replace(/\x1b\[[0-9;]*m/g, '').replace(/\\n/g, ' ');
  if (progress.length > 200) progress = progress.substring(0, 200) + '...';
}
if (!progress && isRunning) progress = 'Working...';

return [{
  json: {
    chatId, outfile, sessionId,
    isComplete, isRunning, isWaiting,
    progress, lastProgress, finalResponse, jsonResult,
    shouldSendProgress: isRunning && progress && progress !== lastProgress && progress !== 'Working...'
  }
}];

// Use $input to get data that flowed through IF node
const inputData = $input.item.json;
const chatId = inputData.chatId;
let text = inputData.finalResponse || '';
const outfile = inputData.outfile;
const jsonResult = inputData.jsonResult;

// Extract session_id from Claude's JSON result (NEW session from this run)
let sessionId = '';
if (jsonResult && typeof jsonResult === 'object') {
  sessionId = jsonResult.session_id || '';
}

// Fallback: try to find session_id in the raw text if jsonResult parsing failed
if (!sessionId && text) {
  const match = text.match(/"session_id":\s*"([^"]+)"/);
  if (match) sessionId = match[1];
}

text = text.replace(/\x1b\[[0-9;]*m/g, '');
text = text.replace(/\n{3,}/g, '\n\n');

if (!text.trim()) text = 'Done!';

// Save session_id to sessions file, then cleanup job
// Only save if we have a valid sessionId
let cleanupCmd;
if (sessionId) {
  cleanupCmd = `SESSIONS_FILE=/tmp/claude-telegram-sessions.json; JOBS_FILE=/tmp/claude-telegram-jobs.json; touch "$SESSIONS_FILE"; if [ ! -s "$SESSIONS_FILE" ]; then echo '{}' > "$SESSIONS_FILE"; fi; TMP=$(mktemp); jq '. + {"${chatId}": "${sessionId}"}' "$SESSIONS_FILE" > "$TMP" && mv "$TMP" "$SESSIONS_FILE"; TMP2=$(mktemp); jq 'del(.["${chatId}"])' "$JOBS_FILE" > "$TMP2" && mv "$TMP2" "$JOBS_FILE"; rm -f "${outfile}"; echo "Session saved: ${sessionId}"`;
} else {
  // No sessionId - just cleanup without saving (shouldn't happen)
  cleanupCmd = `JOBS_FILE=/tmp/claude-telegram-jobs.json; TMP=$(mktemp); jq 'del(.["${chatId}"])' "$JOBS_FILE" > "$TMP" && mv "$TMP" "$JOBS_FILE"; rm -f "${outfile}"; echo "Cleaned (no session)"`;
}

return [{ json: { chatId, text, outfile, sessionId, cleanupCmd, debug: { hasJsonResult: !!jsonResult, sessionIdFound: !!sessionId } } }];

const chatId = $('Format Final Response').item.json.chatId;
const text = $('Format Final Response').item.json.text || '';
const sessionId = $('Format Final Response').item.json.sessionId;
const cleanupCmd = $('Format Final Response').item.json.cleanupCmd;

const MAX_LENGTH = 4000;

// Split message into chunks
const chunks = [];
let currentChunk = '';
const lines = text.split('\n');

for (const line of lines) {
  if ((currentChunk + line + '\n').length > MAX_LENGTH) {
    if (currentChunk.trim()) chunks.push(currentChunk.trim());
    currentChunk = line + '\n';
  } else {
    currentChunk += line + '\n';
  }
}
if (currentChunk.trim()) chunks.push(currentChunk.trim());
if (chunks.length === 0) chunks.push('Done!');

// Create array of items for each chunk
const items = [];
for (let i = 0; i < chunks.length; i++) {
  const prefix = chunks.length > 1 ? `📄 Part ${i + 1}/${chunks.length}\n\n` : '';
  const messageText = prefix + chunks[i];
  items.push({
    json: {
      chatId,
      text: messageText,
      chunkIndex: i + 1,
      totalChunks: chunks.length,
      sessionId,
      cleanupCmd
    }
  });
}

return items;

// Telegram node replaced $json, so reconstruct from Split Into Chunks
const splitChunks = $('Split Into Chunks').all();
const currentIndex = $itemIndex;
const chunkData = splitChunks[currentIndex].json;

return [{ json: {
  chunkIndex: chunkData.chunkIndex,
  totalChunks: chunkData.totalChunks,
  cleanupCmd: chunkData.cleanupCmd,
  telegramResponse: $json
} }];

// Get data from Parse Status (before Telegram node changed it)
const statusData = $('Parse Status').item.json;
const chatId = statusData.chatId;
const progress = (statusData.progress || '').replace(/"/g, "'").replace(/\n/g, ' ').substring(0, 100);

// Build update command with proper escaping
const updateCmd = `JOBS_FILE=/tmp/claude-telegram-jobs.json; TMP=$(mktemp); jq '.["${chatId}"].lastProgress = "${progress}"' "$JOBS_FILE" > "$TMP" && mv "$TMP" "$JOBS_FILE"; echo "Updated"`;

return [{ json: { chatId, progress, updateCmd } }];
